alpha_source:
// Output alpha
  float fAlpha = pPass.cDiffuseMap.a;

#ifdef %VERTALPHA
  fAlpha *= pPass.IN.Color.w;
#endif

#ifndef %DIFFUSE_TEX_BLEND
  if (pPass.bAlphaGlow)
    fAlpha = pPass.IN.Color.w;
#endif

#if %_RT_AMBIENT || %_RT_ALPHABLEND
  fAlpha *= pPass.IN.Ambient.w;
#endif

composition_source:
    if (pPass.bVertexColors)
    {
        cOut.xyz *= pPass.IN.Color.xyz * pPass.IN.Color.xyz;
    }



#if %_RT_AMBIENT
    if (pPass.bAlphaGlow)
    {
        cOut.xyz += pPass.cDiffuseMap.w * pPass.cDiffuseMap.xyz * pPass.fAlphaGlow_Multiplier;
    }
#endif

translated_both:
fAlpha = diffuse[3]
fAlpha *= vertex[3]
if alpha_glow:
        fAlpha = vertex[3]
fAlpha *= opacity
if vertex_rgb:
    color *= vertex[:3] * vertex[:3]
if alpha_glow:
        color += diffuse[3] * diffuse[:3] * multiplier
